// DANGER: In multi-variable 'auto' declarations,
// the type of the FIRST initializer is used for ALL variables.

auto i = 1,       // Type deduced: int
     d = 2.5,     // WARNING: Converted implicitly to int (value 2)
     j = 42;      // Type deduced: int

// Best Practice: Separate declarations for mixed types

auto i_ok = 1;    // i_ok is int
auto d_ok = 2.5;  // d_ok is double
auto j_ok = 42;   // j_ok is int
